mapper.select:
SELECT thread_id AS threadId,parent_turn_id AS parentTurnId,root_turn_id AS rootTurnId,state,
cancel_requested_at_ms AS cancelRequestedAt,requested_at_ms AS requestedAt
FROM ja_conversation_turn WHERE turn_id=#{turnId}

SELECT activity_sequence AS activitySequence,activity_id AS activityId,root_thread_id AS rootThreadId,
task_thread_id AS taskThreadId,actor_thread_id AS actorThreadId,causal_turn_id AS causalTurnId,
kind,summary_json AS summaryJson,created_at_ms AS createdAt
FROM ja_task_activity WHERE task_thread_id=#{taskThreadId} AND activity_sequence>#{afterSequence}
ORDER BY activity_sequence LIMIT #{limit}

mapper.update:
UPDATE ja_task_mailbox_message SET state='CONSUMED',consumed_at_ms=#{occurredAt,typeHandler=io.github.kongweiguang.ja.infrastructure.persistence.mapper.EpochMillisStringTypeHandler,jdbcType=BIGINT},updated_at_ms=#{occurredAt,typeHandler=io.github.kongweiguang.ja.infrastructure.persistence.mapper.EpochMillisStringTypeHandler,jdbcType=BIGINT}
WHERE message_id=#{messageId} AND to_thread_id=#{targetThreadId} AND kind='FOLLOW_UP'
AND state='BOUND' AND bound_turn_id=#{boundTurnId} AND consumed_at_ms IS NULL

UPDATE ja_task_projection SET
revision=revision+1,state=#{state},latest_activity_sequence=#{latestActivitySequence},
unread_count=unread_count+CASE WHEN #{incrementUnread} THEN 1 ELSE 0 END,
latest_safe_summary=#{latestSafeSummary},
started_at_ms=COALESCE(started_at_ms,#{startedAt,typeHandler=io.github.kongweiguang.ja.infrastructure.persistence.mapper.EpochMillisStringTypeHandler,jdbcType=BIGINT}),completed_at_ms=#{completedAt,typeHandler=io.github.kongweiguang.ja.infrastructure.persistence.mapper.EpochMillisStringTypeHandler,jdbcType=BIGINT},updated_at_ms=#{occurredAt,typeHandler=io.github.kongweiguang.ja.infrastructure.persistence.mapper.EpochMillisStringTypeHandler,jdbcType=BIGINT}
WHERE task_thread_id=#{taskThreadId} AND revision=#{expectedRevision}

UPDATE ja_task_projection SET revision=revision+1,latest_activity_sequence=#{latestActivitySequence},
unread_count=unread_count+1,latest_safe_summary=#{latestSafeSummary},updated_at_ms=#{occurredAt,typeHandler=io.github.kongweiguang.ja.infrastructure.persistence.mapper.EpochMillisStringTypeHandler,jdbcType=BIGINT}
WHERE task_thread_id=#{taskThreadId} AND revision=#{expectedRevision}

UPDATE ja_task_projection SET revision=revision+1,
state=CASE WHEN state IN ('QUEUED','RUNNING') THEN state ELSE 'QUEUED' END,
latest_activity_sequence=#{latestActivitySequence},latest_safe_summary=#{latestSafeSummary},
started_at_ms=COALESCE(started_at_ms,#{startedAt,typeHandler=io.github.kongweiguang.ja.infrastructure.persistence.mapper.EpochMillisStringTypeHandler,jdbcType=BIGINT}),completed_at_ms=NULL,updated_at_ms=#{occurredAt,typeHandler=io.github.kongweiguang.ja.infrastructure.persistence.mapper.EpochMillisStringTypeHandler,jdbcType=BIGINT}
WHERE task_thread_id=#{taskThreadId} AND revision=#{expectedRevision}
AND state NOT IN ('WAITING_APPROVAL','WAITING_INPUT','SUSPENDED')

UPDATE ja_task_projection AS p SET descendant_count=(
WITH RECURSIVE descendants(thread_id) AS (
SELECT child_thread_id FROM ja_conversation_lineage WHERE parent_thread_id=p.task_thread_id AND lifecycle='ATTACHED'
UNION ALL
SELECT l.child_thread_id FROM ja_conversation_lineage l JOIN descendants d ON l.parent_thread_id=d.thread_id WHERE
l.lifecycle='ATTACHED'
) SELECT COUNT(*) FROM descendants
),running_descendant_count=(
WITH RECURSIVE descendants(thread_id) AS (
SELECT child_thread_id FROM ja_conversation_lineage WHERE parent_thread_id=p.task_thread_id AND lifecycle='ATTACHED'
UNION ALL SELECT l.child_thread_id FROM ja_conversation_lineage l JOIN descendants d ON l.parent_thread_id=d.thread_id
WHERE l.lifecycle='ATTACHED'
) SELECT COUNT(*) FROM ja_task_projection WHERE task_thread_id IN (SELECT thread_id FROM descendants)
AND state='RUNNING'
),needs_attention_count=(
WITH RECURSIVE descendants(thread_id) AS (
SELECT child_thread_id FROM ja_conversation_lineage WHERE parent_thread_id=p.task_thread_id AND lifecycle='ATTACHED'
UNION ALL SELECT l.child_thread_id FROM ja_conversation_lineage l JOIN descendants d ON l.parent_thread_id=d.thread_id
WHERE l.lifecycle='ATTACHED'
) SELECT COUNT(*) FROM ja_task_projection WHERE task_thread_id IN (SELECT thread_id FROM descendants)
AND state IN ('WAITING_APPROVAL','WAITING_INPUT','SUSPENDED')
),revision=revision+1,updated_at_ms=#{occurredAt,typeHandler=io.github.kongweiguang.ja.infrastructure.persistence.mapper.EpochMillisStringTypeHandler,jdbcType=BIGINT}
WHERE p.root_thread_id=#{rootThreadId}
